private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null) {
        throw new IllegalArgumentException("Node cannot be null");
    }
    TreeNode<T> parent = node.getParent();
    TreeNode<T> grandparent = parent.getParent();
    if (grandparent == null) { // node is the root
        return node;
    }
    TreeNode<T> uncle = parent.getSibling(); // the parent's sibling
    if (uncle != null) {
        uncle.setChild(node.isLeft() ? uncle.getLeft() : uncle.getRight());
    }
    parent.setSibling(null); // break the sibling link
    node.setParent(grandparent);
    grandparent.setChild(node);
    if (node.isLeft()) {
        grandparent.setLeft(parent);
    } else {
        grandparent.setRight(parent);
    }
    return grandparent;
}

