public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        return resolveArguments((ParameterizedType) genericType, targetType);
    }
    return null;
}

private static Class<?>[] resolveArguments(ParameterizedType parameterizedType, Class<?> targetType) {
    Type[] typeArguments = parameterizedType.getActualTypeArguments();
    Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];
    for (int i = 0; i < typeArguments.length; i++) {
        Type typeArgument = typeArguments[i];
        if (typeArgument instanceof Class) {
            resolvedArguments[i] = (Class<?>) typeArgument;
        } else if (typeArgument instanceof TypeVariable) {
            // Resolve type variable using type variable information for the target type
            resolvedArguments[i] = resolveTypeVariable((TypeVariable<?>) typeArgument, targetType);
        } else {
            // Type argument cannot be resolved, return null
            return null;
        }
    }
    return resolvedArguments;
}

private static Class<?> resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType) {
    if (targetType.isAssignableFrom(typeVariable.getGenericDeclaration())) {
        // Type variable is declared in the class declaring the generic parameter
        Type[] types = targetType.getGenericInterfaces();
        for (Type type : types) {
            if (type instanceof ParameterizedType) {
                ParameterizedType parameterizedType = (ParameterizedType) type;
                if (parameterizedType.getRawType().equals(targetType) && parameterizedType.getActualTypeArguments().length == 1) {
                    return resolveTypeVariable(typeVariable, (Class<?>) parameterizedType.getActualTypeArguments()[0]);
                }
            }
        }
        return null;
    } else {
        // Type variable is declared in a superclass or implemented interface
        return resolveTypeVariable(typeVariable, targetType.getSuperclass());
    }
}
