private void pop(final String descriptor) {
    // Check if the descriptor is a method descriptor
    if (descriptor.contains("(")) {
      // Get the argument types of the method descriptor
      String[] argumentTypes = descriptor.substring(1, descriptor.indexOf(")")).split(";");

      // Pop each argument type from the output frame stack
      for (String argumentType : argumentTypes) {
        // Check if the argument type is a primitive type
        if (argumentType.startsWith("[")) {
          // Pop an array of the given primitive type from the output frame stack
          popArray(argumentType);
        } else {
          // Pop a reference object of the given type from the output frame stack
          pop(argumentType);
        }
      }
    } else {
      // Pop a reference object of the given type from the output frame stack
      pop(descriptor);
    }
  }

