    // Iterate over the edges in the Set and add the corresponding vertices to the GraphPath
    for (E edge : tour) {
        result.add(graph.getEdgeSource(edge));
        result.add(graph.getEdgeTarget(edge));
    }

    // Return the resulting GraphPath
    return result;
}

