public static String applyRelativePath(String path, String relativePath) {
    String finalPath;
    if (path == null || relativePath == null) {
        throw new NullPointerException("Path or relative path cannot be null");
    }
    // Check if the relative path is blank
    if (relativePath.trim().equals("")) {
        finalPath = path;
    } else {
        // Check if the relative path has leading '/'
        if (relativePath.startsWith("/")) {
            finalPath = combinePath(path, relativePath);
        } else {
            finalPath = combinePath(path, "/" + relativePath);
        }
    }
    return finalPath;
}

